import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Kế hoạch phần 3.5 còn lại","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/remaining-work/plan.md","filePath":"feature/media-package-campaign/remaining-work/plan.md"}'),c={name:"feature/media-package-campaign/remaining-work/plan.md"};function o(r,e,h,d,s,l){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="ke-hoach-phan-3-5-con-lai" tabindex="-1">Kế hoạch phần 3.5 còn lại <a class="header-anchor" href="#ke-hoach-phan-3-5-con-lai" aria-label="Permalink to &quot;Kế hoạch phần 3.5 còn lại&quot;">​</a></h1><p>Ngày 2026-10-13; dựa trên spec đã chốt. Đây là thiết kế, chưa phải code/test đã chạy.</p><h2 id="_1-thu-tu-ban-giao-va-commit" tabindex="-1">1. Thứ tự bàn giao và commit <a class="header-anchor" href="#_1-thu-tu-ban-giao-va-commit" aria-label="Permalink to &quot;1. Thứ tự bàn giao và commit&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Giai đoạn</th><th>Phạm vi</th><th>Jira</th><th>Exit gate</th></tr></thead><tbody><tr><td>1 (hiện tại)</td><td>Đồng bộ BA/master-plan, spec → plan → task → test</td><td>DA-951, DA-949, DA-950, DA-943</td><td>Quyết định Q1–Q3 đã chốt, tài liệu đủ và diff sạch</td></tr><tr><td>2</td><td>Request create/list/detail/update/cancel thật</td><td>DA-951</td><td>Scope/quyền, Campaign gate, conditional writes và migration kiểm chứng</td></tr><tr><td>3</td><td>Manager receipt/review, accept → một Task Mongo</td><td>DA-951</td><td>Retry/concurrency/rollback, Task provenance, editor handoff</td></tr><tr><td>4</td><td>Directory CRUD/deactivate và nối Campaign</td><td>DA-949 → DA-950</td><td>Owner-only, lifecycle/history, race assign/delete, API/UI thật</td></tr><tr><td>5</td><td>History Package và regression xuyên suốt</td><td>DA-945; DA-943/946/947/948 theo lỗi</td><td>Package → Campaign → Task và Request → Task pass trên dữ liệu thật</td></tr></tbody></table><p>Commit nhỏ bằng tiếng Anh theo đúng Jira: <code>docs(DA-951): ...</code>, <code>feat(DA-951): ...</code>, <code>feat(DA-949): ...</code>, <code>fix(DA-950): ...</code>. Không tạo task ngoài scope bằng cách gắn vào Jira cũ; không tự cập nhật Jira Done. Làm trên feature branch, không code develop. Không commit thay đổi ChromaDB đang có.</p><h2 id="_2-content-request-—-da-951" tabindex="-1">2. Content Request — DA-951 <a class="header-anchor" href="#_2-content-request-—-da-951" aria-label="Permalink to &quot;2. Content Request — DA-951&quot;">​</a></h2><h3 id="contract-du-kien" tabindex="-1">Contract dự kiến <a class="header-anchor" href="#contract-du-kien" aria-label="Permalink to &quot;Contract dự kiến&quot;">​</a></h3><p>Prefix <code>/api/v1/workspaces/{workspaceId}/content-requests</code>.</p><table tabindex="0"><thead><tr><th>Method/path</th><th>Quyền và hành vi</th></tr></thead><tbody><tr><td>POST <code>/</code></td><td>Client; title/description/type/dueDate; Campaign IN_PROGRESS + deployment SUCCEEDED; 201 PENDING</td></tr><tr><td>GET <code>/</code>, GET <code>/{id}</code></td><td>Client/Manager hợp lệ theo Workspace; lọc status, search, page/size; DTO gồm version, requester, reviewer, generatedTaskId và timestamps</td></tr><tr><td>PATCH <code>/{id}</code></td><td>Client tạo Request, PENDING; partial title/description/type/dueDate + expectedVersion</td></tr><tr><td>DELETE <code>/{id}?expectedVersion=...</code></td><td>Client tạo Request, PENDING; CANCELLED, không xóa document</td></tr><tr><td>POST <code>/{id}/receive</code></td><td>Manager của Workspace; PENDING → IN_PROGRESS; expectedVersion</td></tr><tr><td>POST <code>/{id}/accept</code> hoặc <code>/deny</code></td><td>Manager; IN_PROGRESS → terminal; expectedVersion; deny có optional note</td></tr></tbody></table><p>Đối chiếu OpenAPI/routing/ApiResponse/ErrorCode trước implementation. Namespace lỗi dự kiến: REQUEST_NOT_FOUND, REQUEST_NOT_EDITABLE, REQUEST_NOT_CANCELLABLE, REQUEST_STATE_CONFLICT, REQUEST_VERSION_CONFLICT, CAMPAIGN_NOT_DEPLOYED, TASK_SCHEMA_NOT_READY; dùng HTTP 400/403/404/409 theo convention, không trả Mongo/SQL internals. Không cho query param/payload tự khai role/actor/Agency scope. Owner đang là Manager trong Workspace dùng quyền MANAGER hiệu lực, không bị role hệ thống che khuất.</p><p>Trường đầu vào tối thiểu: title không rỗng sau trim, type POST/LIVESTREAM/SURVEY, dueDate ISO-8601 có offset; description plain text. Giới hạn chiều dài và xử lý hạn đã qua phải đối chiếu validation Task/UI hiện có trước code; không tự truncate hoặc đổi múi giờ. PUT legacy nếu có consumer thật phải có adapter, không đổi contract âm thầm.</p><h3 id="persistence-va-canh-tranh" tabindex="-1">Persistence và cạnh tranh <a class="header-anchor" href="#persistence-va-canh-tranh" aria-label="Permalink to &quot;Persistence và cạnh tranh&quot;">​</a></h3><ul><li>Document V2: <code>_id</code>, workspaceId, requestedBy, title, description, type, dueDate, status, version, reviewedBy/reviewedAt, generatedTaskId, decision metadata, createdAt/updatedAt. Audit transition append trong cùng transaction, không mất lịch sử khi retry. Không dùng status Request để mô tả execution của Task.</li><li>Request/update/cancel/receive/deny dùng filter <code>_id + workspaceId + status + version</code>; tăng version atomically, actor lấy từ principal. Không cho stale Client sửa sau receipt; race cancel/receipt có một người thắng.</li><li>Guard create lấy Campaign của đúng Workspace và trạng thái deployment SUCCEEDED. Phối hợp lock/version với endpoint complete để quyết định thứ tự create/complete; không dựa vào status APPROVED hoặc UI cache. Sau complete chỉ chặn tạo mới, các endpoint của Request cũ giữ FSM riêng.</li><li>Accept ưu tiên transaction Mongo chứa tạo Task + cập nhật Request ACCEPTED/generatedTaskId/audit. Xác minh Atlas topology và Spring MongoTransactionManager/config trước dùng; nếu không hỗ trợ thì dừng và trình phương án durable recovery, không ghi ACCEPTED trước rồi bỏ quên Task khi lỗi.</li><li>Task ID ổn định từ requestId, unique partial index <code>(sourceType, sourceRefId)</code> cho CONTENT_REQUEST; nguồn/membership được verify nếu gặp duplicate. Task BACKLOG, campaignId null, assignee/QC null, provenance và defaults khớp TaskDocument; không tạo một bản Task PostgreSQL song song.</li><li>Retry sau commit trả Task cũ; không reinsert/ghi đè Task đã bắt đầu làm. Schema guard kiểm tra đúng index/schema cho Request sources, không chỉ <code>uq_tasks_campaign_work_item</code> của Campaign.</li></ul><h3 id="migration-va-cutover" tabindex="-1">Migration và cutover <a class="header-anchor" href="#migration-va-cutover" aria-label="Permalink to &quot;Migration và cutover&quot;">​</a></h3><p>Implementation giai đoạn 2 (2026-10-13): API camelCase, <code>requests.v2.*</code> vi/en. Title bắt buộc, trim và tối đa 255; description bắt buộc là chuỗi (cho phép rỗng), tối đa 10.000; type chỉ POST/LIVESTREAM/SURVEY; dueDate bắt buộc ISO-8601 có offset. Chưa bổ sung quy tắc hạn phải ở tương lai khi BA chưa yêu cầu. PATCH bắt buộc <code>expectedVersion &gt;= 1</code> và ít nhất một field được phép; DELETE nhận <code>expectedVersion</code> qua query, hủy mềm và trả 204. Search tối đa 100; page &gt;= 0, size 1–50 (mặc định 20), sort createdAt/id giảm dần. UI có QueryClientProvider riêng, không sửa provider/layout gốc; form giữ input khi 409, cảnh báo bỏ thay đổi, ngăn gửi lặp và giữ nguyên timestamp khi không sửa hạn.</p><ol><li>Chỉ read-only inventory Atlas được phép: collection options, fields/types/status counts, thiếu workspace/type/dueDate, liên kết editor/task và nguồn dữ liệu. Báo các record không ánh xạ được; SUBMITTED có thể tương đương PENDING nhưng không tự quyết định ASSIGNED/APPROVED/REJECTED.</li><li>Viết migration JS mới có preflight, idempotency, dry-run và count verification; backup trước backfill. Nếu có legacy ambiguous thì abort trước mọi write; không xóa/ghi đè hoặc nhét type/date mặc định để chạy qua validator.</li><li>Đồng bộ <code>docs/database/init-mongo.js</code>, indexes và hướng dẫn <code>mongo-atlas-migrations.md</code>; không sửa migration đã merge hoặc init shared Atlas. Chạy schema parity trên DB test riêng khi được phép.</li><li>Chạy validation/index preflight trước bật API; rollout backend/gateway rồi UI. Rollback app không revert dữ liệu ACCEPTED/CANCELLED hay drop index; backup/restore chỉ theo phê duyệt riêng. Giữ migration cũ.</li></ol><h3 id="chi-tiet-giai-đoan-3-—-2026-10-13" tabindex="-1">Chi tiết giai đoạn 3 — 2026-10-13 <a class="header-anchor" href="#chi-tiet-giai-đoan-3-—-2026-10-13" aria-label="Permalink to &quot;Chi tiết giai đoạn 3 — 2026-10-13&quot;">​</a></h3><ul><li>Tách <code>ContentRequestReviewService</code> và controller riêng cho receive/accept/deny để không đổi constructor/luồng create/update/cancel đã kiểm thử. Payload whitelist <code>expectedVersion</code> (integer &gt;=1), deny thêm optional plain-text <code>note</code> &lt;=2000.</li><li>Receive/deny CAS một document, reviewer lấy từ principal. Receive chỉ PENDING; accept/deny chỉ IN_PROGRESS; stale version 409. Không kiểm tra trạng thái Campaign ở các thao tác Request đã tồn tại. Note lưu <code>decisionNote</code>, <code>decidedBy/decidedAt</code> và trong audit snapshot; không ghi đè reviewer đã tiếp nhận.</li><li>Accept dùng Java driver <code>ClientSession.withTransaction</code> và MongoOperations gắn đúng session cho cả Request và Task; SNAPSHOT + MAJORITY. Driver retry transient transaction/unknown commit theo cơ chế chuẩn. Không đăng ký MongoTransactionManager bean toàn cục vì có thể làm Boot ngừng tạo JPA transaction manager của module khác.</li><li>Kiểm tra <code>hello</code> read-only: replica-set/mongos, logicalSessionTimeoutMinutes, maxWireVersion &gt;=7; nếu không hỗ trợ trả 503 và hỏi lại, không fallback partial writes. Không chạy <code>hello</code> hay schema/index commands bên trong transaction.</li><li>Task ID UUID ổn định từ <code>content-request:{requestId}</code>; unique partial index <code>(sourceType, sourceRefId)</code> chỉ CONTENT_REQUEST. Không upsert/save Task đã có. Request ACCEPTED retry trả cùng Task nếu scope/source/type/id còn đúng; không sửa Task status/name/content/assignment đã được workflow E51 thay đổi.</li><li>GET <code>/{id}/task</code> cung cấp Task summary read-only theo quyền đọc Request (id, name, type, dueDate, status). Chỉ effective Workspace MANAGER với Task POST có link vào editor hiện có; Client xem kết quả/status, không được mở editor hoặc nhận quyền mới.</li><li>Migration phase 3 riêng, mặc định dry-run, kiểm tra duplicate/missing provenance trước tạo unique index; giữ migration phase 2. Init đồng bộ decision metadata/index.</li><li>UI detail thêm actions theo capabilities server; confirmation cho accept/deny, giải thích accept sẽ tạo một Task; loading chống double submit, 409 giữ note. Giữ theme/tokens/typography hiện tại, không đổi layout/root hoặc UI thành viên khác.</li><li>Runtime kiểm thử transaction chỉ trên DB local cô lập khi có Docker; không ghi vào Atlas hoặc dùng dữ liệu Workspace/account đang test của team.</li><li>Tài liệu kỹ thuật tham chiếu: <a href="https://docs.spring.io/spring-data/mongodb/reference/mongodb/client-session-transactions.html" target="_blank" rel="noreferrer">Spring Data session-scoped operations</a> và <a href="https://www.mongodb.com/docs/drivers/java/sync/v5.0/fundamentals/transactions/" target="_blank" rel="noreferrer">MongoDB Java driver 5.0 transactions</a>.</li><li>Người dùng chốt: Task mới giữ default hiện có, BACKLOG, assignee/QC null, <code>requiresClientApproval=false</code>; Manager cấu hình ở bước xác định chi tiết E51. Read-only hello Atlas đã xác minh replicaSet=true, sessions=true, maxWireVersion=25. Retry ACCEPTED chấp nhận expectedVersion của lần accept gốc hoặc phiên bản terminal hiện tại, không nhận version tùy ý và không append thêm audit.</li></ul><h3 id="cac-repo-file-du-kien" tabindex="-1">Các repo/file dự kiến <a class="header-anchor" href="#cac-repo-file-du-kien" aria-label="Permalink to &quot;Các repo/file dự kiến&quot;">​</a></h3><ul><li>Business: document/repository Request mới, scoped controller/service/DTO/ErrorCode, generic Task source store và schema guard; phối hợp TaskContentService/editor owner, không sửa thuật toán Yjs.</li><li>Gateway: kiểm tra route policy cho prefix Workspace, principal và lỗi; giữ auth/WebSocket hiện có.</li><li>Web: <code>pages/requests</code>, typed API service/model mới, API thật theo workspaceId. Không đổi global mock/client-profile consumers ngoài phạm vi; bỏ assign/my-tasks từ UI Request V2 vì thuộc E51. Chỉ thay UI Workspace Request, không đổi shared layout module khác.</li><li>Locales: <code>src/i18n/locales/{vi,en}/requests.json</code>; keys song song, namespace trạng thái riêng. Giữ thiết kế hiện có, light/dark, mobile, dirty form/conflict state. Đọc skill UI phù hợp trước khi chỉnh UI và Playwright skill trước browser automation.</li></ul><h2 id="_3-đoi-tac-—-da-949-950" tabindex="-1">3. Đối tác — DA-949/950 <a class="header-anchor" href="#_3-đoi-tac-—-da-949-950" aria-label="Permalink to &quot;3. Đối tác — DA-949/950&quot;">​</a></h2><p>Xem <a href="./../partner-directory/plan.html">partner-directory/plan.md</a>. Tái dùng entity/service liên kết DA-950; không AI/booking. Migration SQL và init parity chỉ ở giai đoạn 4, chưa chạy trong giai đoạn 1.</p><h2 id="_4-phan-package-campaign-con-lai" tabindex="-1">4. Phần Package/Campaign còn lại <a class="header-anchor" href="#_4-phan-package-campaign-con-lai" aria-label="Permalink to &quot;4. Phần Package/Campaign còn lại&quot;">​</a></h2><ul><li>DA-945: giữ giới hạn clientProposalCount hiện có, thêm lịch sử immutable version/actor/action/snapshot và API đọc; terms/version/reset approvals/event cùng transaction. Không bịa lịch sử trước khi có event; đánh dấu snapshot legacy là baseline.</li><li>DA-943: không scheduler; regression gate/redirect/Manager settings/Chat.</li><li>DA-946/947/948: smoke approval đồng thời, một Campaign/Workspace, deploy/retry, Task source, editor và complete có lý do. Full negotiation history/withdraw approval chỉ implement sau đối chiếu spec sở hữu, không mở rộng ngầm.</li><li>Không seed account mới hoặc sửa dữ liệu dùng chung. Cần quyền riêng trước test mutation trên Atlas/local có dữ liệu của team. Dùng account test hiện có và fixture kiểm soát, cleanup không đụng Workspace khác.</li></ul>',24)])])}const u=t(c,[["render",o]]);export{p as __pageData,u as default};
